from allow_missing_motors import Motor

# Set up.
prime_hub = PrimeHub()
leftMotor = Motor(Port.E, Direction.COUNTERCLOCKWISE)
rightMotor = Motor(Port.A, Direction.CLOCKWISE)
DriveBase1 = DriveBase(leftMotor, rightMotor, 56, 4.375 * 25.4)
attachment = Motor(Port.B, Direction.CLOCKWISE)
colorSensor = ColorSensor(Port.C)
controller = XboxController()
speed = 1.5
watch = StopWatch()


# The main program starts here.
print('Hello, Pybricks!')
DriveBase1.reset(0, 0)
watch.reset()
while not Button.A in controller.buttons.pressed():
    DriveBase1.drive(speed * controller.joystick_left()[1], speed * controller.joystick_right()[0])
    if Button.LB in controller.buttons.pressed():
        attachment.dc(50)
    elif Button.RB in controller.buttons.pressed():
        attachment.dc(-50)
    else:
        attachment.dc(0)
    if Button.B in controller.buttons.pressed():
        DriveBase1.reset(0, 0)
